SELECT tblJOB.MoldDesignID, tblJOB.DeliveryDeadline, tblProcessingCode.ProcessingName, tblWorkLog.ProcessingDeadlineID, tblWorkLog.ProcessingTime, tblWorkLog.ProcessingDate, tblWorkLog.ProcessingNotes, tblWorkLog.ProcessingCodeID, tblJOB.JobID, tblEmployee.EmployeeName, tblEmployee.EmployeeID, tblProcessingDeadline.ProcessingStatusID, tblProcessingDeadline.ProcessingDeadline, tblMoldDesign.MoldDesignName
