SELECT tblEmployee.EmployeeName, tblProcessingCode.ProcessingName, tblJOB.JobName, tblProcessingStatus.ProcessingStatus, tblWorkLog.ProcessingTime, tblWorkLog.ProcessingDate, tblWorkLog.ProcessingNotes, tblJOB.JobID, tblProcessingCode.ProcessingCodeID, tblWorkLog.CompanyID, tblProcessingDeadline.ProcessingDeadlineID, tblProcessingDeadline.MachiningCustomerID
