WHERE (((tblWorkLog.ProcessingDate)=Date()) AND ((tblWorkLog.CompanyID) Is Null) AND ((tblProcessingDeadline.ProcessingDeadlineID)<>2205) AND ((tblProcessingDeadline.MachiningCustomerID)<>3));

