SELECT Left([CustomerShortName],1) AS ChuCaiDau, tblRack.RackLocation, tblRackLayer.RackLayerNumber, tblMoldDesign.MoldDesignName, tblMoldDesign.MoldDesignCode, tblMoldCutter.MoldCutterNotes, tblRack.RackSymbol, tblCutter.*, tblRackLayer.RackLayerNotes, tblMoldDesign.MoldDesignName AS MaKHuonKethop, tblRack.RackID, tblCutter.CutterType AS ShareType
