WHERE (((tblCutter.CutterType)<>"スタッキング"));

SELECT tblEmployee.EmployeeName, tblProcessingCode.ProcessingName, tblJOB.JobName, tblProcessingStatus.ProcessingStatus, tblWorkLog.ProcessingTime, tblWorkLog.ProcessingDate, tblWorkLog.ProcessingNotes, tblJOB.JobID, tblProcessingCode.ProcessingCodeID, tblWorkLog.CompanyID, tblMoldDesign.MoldDesignName, tblProcessingDeadline.ProcessingDeadlineID, tblProcessingDeadline.MachiningCustomerID
