SELECT tblWorkLog.WorkLogID, tblWorkLog.ProcessingDeadlineID, tblWorkLog.EmployeeID, tblWorkLog.ProcessingCodeID, tblWorkLog.ProcessingTime, tblWorkLog.ProcessingDate, tblWorkLog.ProcessingNotes, tblWorkLog.Noidunglienlac, tblEmployee.EmployeeName, tblJOB.JobName, tblProcessingDeadline.JobID
