WHERE (((tblWorkLog.EmployeeID)=Forms!frmDAILYworkLog!cboEmployeeID) And ((tblWorkLog.ProcessingDate)=Forms!frmDAILYworkLog!txtProcessingDate));

SELECT tblMold.MoldName, tblMoldBorrow.JaeNo, IIf([BorrowYear] Is Not Null,[BorrowYear] & "/" & [BorrowMonth],"") AS BorrowPeriod, tblMoldBorrow.EquipmentNo, tblMoldBorrow.AssetName, tblMoldBorrow.DrawingNo, tblMoldBorrow.Notes, tblMold.RackLayerID, tblRackLayer.RackCompanyNote, tblMold.MoldOnCheckList
