WHERE (((tblMold.MoldOnCheckList)=Yes));

SELECT tblMold.MoldName, tblMoldBorrow.[No], IIf(([BorrowingYear] Is Not Null And [BorrowingMonth] Is Not Null),[BorrowingYear] & "/" & [BorrowingMonth],"") AS BorrowPeriod, tblMoldBorrow.EquipmentNumber, tblMoldBorrow.AssetName, tblMoldBorrow.DrawingNumber, tblMoldBorrow.Notes, tblMold.RackLayerID, tblRackLayer.RackCompanyNote, tblMold.MoldOnCheckList, tblMold.ItemTypeID, tblMoldDesign.DrawingNumber
