SELECT tblMoldBorrow.[No], IIf(([BorrowingYear] Is Not Null And [BorrowingMonth] Is Not Null),[BorrowingYear] & "/" & [BorrowingMonth],"") AS BorrowPeriod, tblMoldBorrow.EquipmentNumber, tblMoldBorrow.AssetName, tblMoldBorrow.DrawingNumber, tblMoldBorrow.Notes, tblMold.MoldName, tblRackLayer.RackLayerID, tblRackLayer.RackCompanyNote
