SELECT tblWorkLog.ProcessingDate, tblWorkLog.ProcessingTime, tblProcessingCode.ProcessingName, tblWorkLog.ProcessingNotes, tblJOB.JobID, Year([ProcessingDate]) AS Nam, Month([ProcessingDate]) AS ThangTheoLich, IIf(Day([ProcessingDate])>=21 And (Month([ProcessingDate])+1<=12),Month([ProcessingDate])+1,(IIf(Day([ProcessingDate])>=21 And (Month([ProcessingDate])+1=13),1,Month([ProcessingDate])))) AS ThangTinhLuong, IIf(Day([ProcessingDate])>=21 And (Month([ProcessingDate])+1)=13,Year([ProcessingDate])+1,Year([ProcessingDate])) AS NamTinhLuong, [NamTinhLuong] & " 年" & " " & [ThangTinhLuong] & "月" AS ThangNamLuong, [NamTinhLuong] & Format([ThangTinhLuong],"00") AS Yearmonth, tblWorkLog.EmployeeID
