FROM tblProcessingStatus INNER JOIN (tblMoldDesign INNER JOIN (tblJOB INNER JOIN (tblProcessingCode INNER JOIN (tblProcessingDeadline INNER JOIN (tblEmployee INNER JOIN tblWorkLog ON tblEmployee.EmployeeID = tblWorkLog.EmployeeID) ON tblProcessingDeadline.ProcessingDeadlineID = tblWorkLog.ProcessingDeadlineID) ON tblProcessingCode.ProcessingCodeID = tblWorkLog.ProcessingCodeID) ON tblJOB.JobID = tblProcessingDeadline.JobID) ON tblMoldDesign.MoldDesignID = tblJOB.MoldDesignID) ON tblProcessingStatus.ProcessingStatusID = tblProcessingDeadline.ProcessingStatusID
