SELECT tblWorkLog.ProcessingDate, tblWorkLog.ProcessingTime, tblProcessingCode.ProcessingName, tblWorkLog.ProcessingNotes, tblJOB.JobID, Year([ProcessingDate]) AS Nam, Month([ProcessingDate]) AS [Thang theo lich], IIf(Day([ProcessingDate])>=21 And (Month([ProcessingDate])+1<=12),Month([ProcessingDate])+1,(IIf(Day([ProcessingDate])>=21 And (Month([ProcessingDate])+1=13),1,Month([ProcessingDate])))) AS [Thang tinh luong], IIf(Day([ProcessingDate])>=21 And (Month([ProcessingDate])+1)=13,Year([ProcessingDate])+1,Year([ProcessingDate])) AS [Nam tinh luong], [nam tinh luong] & " 年" & " " & [thang tinh luong] & "月" AS ThangNamLuong, tblEmployee.EmployeeName, tblJOB.JobName
